quizzes.question:
阅读以下程序并预测输出（可用空格分隔各行）。无标准输入。预置 source.txt 含三个字母 abc 和一个换行

#include <stdio.h>

int main(void) {
    FILE*in=fopen("source.txt","r");if(!in)return 1;
    FILE*out=fopen("copy.txt","w");if(!out){fclose(in);return 1;}
    int ch,n=0,ok=1;while((ch=fgetc(in))!=EOF){if(fputc(ch,out)==EOF){ok=0;break;}n++;}
    if(ferror(in))ok=0;if(fclose(in)!=0)ok=0;if(fclose(out)!=0)ok=0;
    if(!ok)return 1;printf("%d\n",n);
    return 0;
}

