challenge.solution:
#include <stdio.h>

int main(void) {
    FILE*f=fopen("end.txt","r");if(!f)return 1;
    while(fgetc(f)!=EOF){}
    if(ferror(f)){fclose(f);return 1;}
    int before=feof(f)!=0;clearerr(f);int after=feof(f)!=0;
    int ch=fgetc(f);if(ch!=EOF){fclose(f);return 1;}int again=feof(f)!=0;
    if(fclose(f)!=0)return 1;printf("%d %d %d\n",before,after,again);
    return 0;
}
